style.css:
@-moz-document domain("chefkoch.de") {
/* ====================================================================
     Palette via design-system custom properties
     Chefkoch's frontend is driven by --ck-color-* tokens on :root.
     Retheming these recolors most surfaces/text/borders site-wide; the
     element rules below mop up everything that is hardcoded.
     ==================================================================== */
  :root {
    color-scheme: dark !important;
    --ck-color-bg-primary: #14181d !important;   /* page surface (#f6f7f4) */
    --ck-color-bg-header:  #0d1117 !important;    /* header band (#e2ece3) */
    --ck-color-text-primary: #e6edf3 !important;  /* body text (#212018) */
    --ck-color-border: #262c33 !important;        /* hairlines (#ddd) */
    /* keep the brand green – it stays readable on dark */
    --ck-color-brand-green: #4cae5e !important;
    --ck-color-brand-green-dark: #3fa052 !important;
  }

  /* ====================================================================
     Base surfaces  (the "w-" shell + "ds-" content container)
     ==================================================================== */
  html, body {
    background-color: #14181d !important;
    color: #e6edf3 !important;
  }
  body, main, .ds-container, .ds-bg-container,
  .w-header, .w-header.w-scope, .w-header__menu, .w-main-menu, .w-flyout,
  .w-mobile-menu, .w-funke-banner, .w-footer, .w-footer.w-scope, #content,
  .content, .recipe, .ds-page {
    background-color: #14181d !important;
  }
  /* the CMS "stage" wave (magazine overview etc.) ships as a cream #F6F7F4
     SVG background-image on body that paints over our dark bg and washes
     out the light heading — drop the decorative image on dark */
  body.ds-cms-bg-home, body[class*="ds-cms-bg"] {
    background-image: none !important;
  }

  /* Soften every default light border to a subtle dark line */
  * { border-color: #262c33 !important; }

  /* ====================================================================
     Header / global nav  ("w-" shell)
     ==================================================================== */
  .w-header, .w-header.w-scope, .w-funke-banner {
    background-color: #0d1117 !important;
    color: #e6edf3 !important;
    border-bottom: 1px solid #262c33 !important;
  }
  /* backdrop pseudo behind the sticky header ships solid white and peeks
     out as a sliver below the nav — recolor it to the header bg */
  #w-header::before, .w-header::before, .w-header.w-scope::before {
    background-color: #0d1117 !important;
  }
  .w-header__menu, .w-main-menu, .w-flyout, .w-mobile-menu, .w-mobile-menu-head {
    background-color: #0d1117 !important;
    color: #e6edf3 !important;
  }
  .w-header a, .w-main-menu a, .w-flyout a, .w-funke-banner,
  .w-header__actions, .w-menu-button, .ds-tab-nav__link {
    color: #e6edf3 !important;
  }
  .w-header a:hover, .w-main-menu a:hover, .ds-tab-nav__link:hover { color: #ffffff !important; }
  /* logo glyphs (green hat + dark wordmark) -> keep hat green, lift letters */
  [data-testid="logo-hat"], [data-testid="logo-hat"] path { fill: #4cae5e !important; }
  [data-testid="logo-letters"], [data-testid="logo-letters"] path { fill: #e6edf3 !important; }
  /* header search field */
  .w-header__search, .w-header__search input, .w-header__search form {
    background-color: #1c2128 !important;
    color: #e6edf3 !important;
    border-color: #2d333b !important;
  }
  .w-header__search input::placeholder { color: #8b949e !important; }
  .w-header__search svg, .w-header svg { fill: #c4cdd6 !important; }

  /* PLUS flyout / menu panels */
  .w-flyout__col, .w-flyout__teaser-link, .w-flyout__menu-btn {
    background-color: #1c2128 !important;
    color: #e6edf3 !important;
  }

  /* ====================================================================
     Typography (shared)
     ==================================================================== */
  h1, h2, h3, h4, h5, h6,
  .ds-h1, .ds-h2, .ds-h3, .ds-h4,
  .ds-heading, .ds-text-blackberry, .ds-text-semi-bold {
    color: #e6edf3 !important;
  }
  p, li, dd, dt, span, td, th, label, figcaption, time, small, blockquote,
  .ds-text-sans, .ds-text-basmati, .recipe-text {
    color: #c4cdd6 !important;
  }
  /* secondary / caption / "olive" greys (#595852, #807f78) are too dark on
     a dark surface — lift them to a readable muted grey */
  .ds-text-caption, .ds-text-olive-medium, .ds-text-olive,
  .ds-text-secondary, .ds-text-muted, .ds-recipe-card__description,
  .ds-collection-card__info-value, .ds-collection-card__info-label,
  .ds-collection-card__date, small.ds-text-caption,
  /* comment / author meta timestamp ("vor 2 Stunden") ships as a dark
     olive #595852 that fails contrast on the dark card -> muted grey */
  .ds-author__caption, .ds-author__meta .ds-author__caption {
    color: #9aa5af !important;
  }
  /* monochrome glyph-font icons default to a dark olive — lift to muted grey */
  i.chefkoch-icons, .chefkoch-icons,
  .ds-collection-card__info-icon, .recipe-meta-property-group__icon {
    color: #9aa5af !important;
  }

  /* ---- Links: keep the Chefkoch green, lifted for dark contrast ---- */
  a, .ds-text-link, a.ds-text-link {
    color: #4cae5e !important;
  }
  a:hover, .ds-text-link:hover { color: #6fd382 !important; }
  /* breadcrumbs */
  .ds-breadcrumb, .ds-breadcrumb__item, .ds-breadcrumb__item--current { color: #8b949e !important; }
  .ds-breadcrumb__link { color: #c4cdd6 !important; }
  .ds-breadcrumb__link:hover { color: #4cae5e !important; }

  /* ====================================================================
     Recipe page: ingredients, quantity, nutrition, meta, steps
     ==================================================================== */
  /* ingredients table */
  .ds-ingredients-table,
  .ds-ingredients-table__tr,
  .recipe-ingredients { background-color: transparent !important; color: #c4cdd6 !important; }
  .ds-ingredients-table__th,
  .ds-ingredients-table__head,
  .ds-ingredients-table__headline {
    background-color: #1c2128 !important;
    color: #e6edf3 !important;
    border-color: #2d333b !important;
  }
  .ds-ingredients-table__td,
  .ds-ingredients-table__td--first,
  .ds-ingredients-table__ingredient,
  .ds-ingredients-table__ingredient-name {
    color: #c4cdd6 !important;
    border-color: #2d333b !important;
  }
  /* PLUS paywall fade over long ingredient lists is a white gradient
     (::before) — recolor it to fade into the dark page bg instead */
  .recipe-ingredients--fadeout::before,
  .recipe-ingredients--fadeout::after,
  [class*="fadeout"]::before, [class*="fadeout"]::after {
    background-image: linear-gradient(rgba(20,24,29,0), #14181d) !important;
  }

  /* portion / quantity control */
  .ds-quantity-control,
  .ds-quantity-control__input-wrap,
  .ds-quantity-control__input {
    background-color: #1c2128 !important;
    color: #e6edf3 !important;
    border-color: #2d333b !important;
  }
  .ds-quantity-control__up, .ds-quantity-control__down,
  .ds-quantity-control__label, .ds-quantity-control__amount { color: #e6edf3 !important; }

  /* nutrition block */
  .ds-nutrition, .ds-nutrition__layout { background-color: transparent !important; }
  .ds-nutrition__cell {
    background-color: #1c2128 !important;
    border-color: #2d333b !important;
  }
  .ds-nutrition__title, .ds-nutrition__value, .ds-nutrition__labels { color: #e6edf3 !important; }
  .ds-nutrition__icon { fill: #c4cdd6 !important; }

  /* recipe meta (prep time, difficulty, calories) */
  .recipe-meta-property-group,
  .recipe-meta-property-group__cell { background-color: transparent !important; }
  .recipe-meta-property-group__title, .recipe-meta-property-group__value { color: #e6edf3 !important; }
  .recipe-meta-property-group__detail, .recipe-meta-property-group__labels { color: #9aa5af !important; }
  .recipe-meta-property__link { color: #4cae5e !important; }

  /* ====================================================================
     Cards, teasers, editorial tiles (home + search + recipe sidebar)
     ==================================================================== */
  .ds-teaser-link, .ds-editorial-card, .ds-subscription-card,
  .ds-slider-image, .ds-card, .ds-recipe-card, .rsel-recipe,
  .ds-rounded-2, .ds-rounded-s-6, .ds-bg-blackberry,
  .ds-collection-card, .ds-collection-card__infos, .ds-category-card,
  .ds-category-card--garlic, .ds-profile-card, .ds-profile-card__bottom,
  .recipesOfTheDay, .recipe-of-the-day, .ds-bg-garlic {
    background-color: #1c2128 !important;
    color: #c4cdd6 !important;
    border-color: #2d333b !important;
  }
  .ds-teaser-link__headline, .ds-editorial-card__headline,
  .ds-collection-card__headline, .ds-category-card__headline,
  .ds-category-card__name, .ds-collection-card__title,
  .ds-slider-image__info, .ds-slider-image__info-link { color: #e6edf3 !important; }
  .ds-teaser-link:hover, .ds-editorial-card:hover, .rsel-recipe:hover,
  .ds-collection-card:hover, .ds-category-card:hover { background-color: #21262d !important; }
  /* image-wrap skeleton placeholders (light-green #e2ece3 behind thumbnails) */
  .ds-teaser-link__image-wrap, .ds-editorial-card__image-wrap,
  .ds-slider-image__image-wrap, .ds-recipe-card__image-wrap,
  .ds-collection-card__image-wrap, .ds-category-card__image-wrap,
  [class*="__image-wrap"] { background-color: #1c2128 !important; }
  /* profile-card top: a cream #f6f7f4 plate painted by ::before sits behind the
     circular avatar/brand-logo image (home "Profis", magazine "Rezepte von
     Profis"). The avatar img keeps its own circle, so darken just the plate. */
  .ds-profile-card__top { background-color: #1c2128 !important; }
  .ds-profile-card__top::before, .ds-profile-card__top::after {
    background-color: #1c2128 !important;
    background-image: none !important;
  }
  /* hero teaser "shape": the decorative wave at the bottom of the .ds-main-slide
     is an SVG path filled white to blend into the light page — on dark it reads
     as a bright wave, so fill it with the page bg to vanish into the surface */
  .ds-main-slide__shape svg path, .ds-main-slide__shape path { fill: #14181d !important; }
  /* "recipe of the day" inner highlight panel uses the light-green tint */
  .recipesOfTheDay .ds-rounded-4, .recipesOfTheDay [class*="ds-pv-"],
  .recipesOfTheDay > div { background-color: transparent !important; }
  /* PLUS subscription cards keep an elevated tint (incl. inner panels) */
  .ds-subscription-card--plus,
  .ds-subscription-card__head, .ds-subscription-card__body,
  .ds-subscription-card__footer { background-color: #20222a !important; }
  .ds-subscription-card__head *, .ds-subscription-card__body *,
  .ds-subscription-card__footer * { color: #e6edf3 !important; }

  /* newsletter / promo bands painted in the light-green header tint (#e2ece3) */
  .ds-newsletter, .ds-newsletter-box, .newsletter, .newsletter-box,
  .ds-bg-mint, .ds-bg-green-light, [class*="newsletter"],
  [class*="__newsletter"], .ds-promo-band, .ds-cta-band {
    background-color: #1c2128 !important;
    color: #e6edf3 !important;
    border-color: #2d333b !important;
  }
  [class*="newsletter"] h2, [class*="newsletter"] h3,
  [class*="newsletter"] p, [class*="newsletter"] span { color: #e6edf3 !important; }

  /* video "play" badge: white circle behind the glyph -> dark translucent */
  .ds-play-badge, .ds-card-badge--play, [class*="play-badge"] {
    background-color: rgba(13,17,23,0.72) !important;
  }
  .ds-play-badge__icon, [class*="play-badge"] i, [class*="play-badge"] svg {
    color: #ffffff !important; fill: #ffffff !important;
  }

  /* author chips */
  .ds-author, .ds-author__meta { background-color: transparent !important; }
  .ds-author__name, .ds-author__name-prefix { color: #c4cdd6 !important; }
  .ds-author__avatar { background-color: #1c2128 !important; }
  /* card / sidebar author labels keep the site "blackberry" dark text on the
     dark card -> force a high-specificity light override that wins */
  .ds-card .ds-author__name, .ds-recipe-card .ds-author__name,
  .ds-teaser-link .ds-author__name, .ds-collection-card .ds-author__name,
  .ds-author .ds-author__name, .ds-author .ds-author__name-prefix,
  .ds-author__name.ds-text-blackberry, .ds-author__name-prefix.ds-text-blackberry,
  [class*="author"] .ds-text-blackberry, .ds-author [class*="name"] {
    color: #c4cdd6 !important;
  }

  /* ====================================================================
     Recipe COMMENTS — light comment cards on the dark page
     The broad p/li/span/div text rule paints comment bodies near-white,
     so the card MUST become an elevated dark surface to read.
     ==================================================================== */
  .ds-comment, .ds-comment--answers-expanded, .ds-comment__answers,
  .ds-comment__body, .ds-comment__content, .ds-comment__main,
  [class*="ds-comment"] {
    background-color: #1c2128 !important;
    border-color: #2d333b !important;
  }
  .ds-comment__text, .ds-comment__body, .ds-comment__content,
  .ds-comment p, .ds-comment span, .ds-comment li {
    color: #c4cdd6 !important;
  }
  .ds-comment__author, .ds-comment__author-name { color: #e6edf3 !important; }
  .ds-comment__date, .ds-comment__meta { color: #9aa5af !important; }

  /* ====================================================================
     Recipe AUTHOR-BOX — light cream band
     ==================================================================== */
  .author-box, .author-box__content, .author-box__inner,
  [class*="author-box"] {
    background-color: #1c2128 !important;
    border-color: #2d333b !important;
  }
  .author-box, .author-box *, [class*="author-box"] * { color: #c4cdd6 !important; }
  .author-box h1, .author-box h2, .author-box h3,
  .author-box__name, .author-box__title { color: #e6edf3 !important; }
  .author-box a, [class*="author-box"] a { color: #4cae5e !important; }

  /* ====================================================================
     Recipe PREP-TIMES bar (Gesamtzeit / Arbeitszeit / Koch-/Backzeit)
     Light cream band -> elevated dark surface + lift the metric labels.
     ==================================================================== */
  .ds-preparation-times, .ds-preparation-times__main,
  .ds-preparation-times__detail, .ds-preparation-times__item,
  [class*="preparation-times"] {
    background-color: #1c2128 !important;
    border-color: #2d333b !important;
  }
  .ds-preparation-times__main, .ds-preparation-times__detail,
  .ds-preparation-times__value, .ds-preparation-times__time,
  [class*="preparation-times"] [class*="value"],
  [class*="preparation-times"] [class*="time"] { color: #e6edf3 !important; }
  .ds-preparation-times__label, .ds-preparation-times__title,
  [class*="preparation-times"] [class*="label"],
  [class*="preparation-times"] [class*="title"] { color: #9aa5af !important; }

  /* ====================================================================
     Recipe STEP-NUMBER badges (the "1,2,3..." prep-step circles)
     Light grey number on light-mint circle -> dark circle + light number.
     ==================================================================== */
  .ds-rounded-6.ds-title-xs, [class*="ds-rounded-6"].ds-title-xs {
    background-color: #1c2128 !important;
    color: #e6edf3 !important;
    border-color: #2d333b !important;
  }

  /* ====================================================================
     "CHEFKOCH Check" widget (Kniff / Stolperfalle / "richtig gut")
     Each tip is a cream #f6f7f4 .ck-check__item panel with a white
     circular .ck-check__badge behind the icon — the now-light body text
     washes out on it. Repaint the panel + badge to the dark surface.
     ==================================================================== */
  .ck-check__item {
    background-color: #1c2128 !important;
    border-color: #2d333b !important;
  }
  .ck-check__badge, .ck-check__badge--tip,
  .ck-check__badge--warning, .ck-check__badge--success {
    background-color: #21262d !important;
  }
  .ck-check__label, .ck-check__text { color: #e6edf3 !important; }
  .ck-check__body, .ck-check__body p { color: #c4cdd6 !important; }
  .ck-check__badge i, .ck-check__badge .chefkoch-icons { color: #9aa5af !important; }

  /* recipe-header "TOP-REZEPT" award pill ships the light-green #e2ece3
     header tint with a grey laurel + grey label that wash out on it ->
     elevated dark pill with a light label (a short pill the height-gated
     light-surface audit skips) */
  .editorial-info-card__pill {
    background-color: #21262d !important;
    border-color: #2d333b !important;
  }
  .editorial-info-card__pill-label { color: #e6edf3 !important; }
  .editorial-info-card__pill .chefkoch-icons,
  .editorial-info-card__pill i { color: #9aa5af !important; }

  /* "Nutze Chefkoch ohne Banner" ad-free link is a dark olive on the dark
     page -> lift to a readable muted grey */
  .ads__adfree-link, [class*="adfree-link"] { color: #9aa5af !important; }

  /* ====================================================================
     Buttons
     ==================================================================== */
  /* primary / conversion green CTAs keep the brand fill */
  .ds-btn--primary, .ds-btn--conversion, .ds-btn--save {
    background-color: #3b8047 !important;
    color: #ffffff !important;
    border-color: #3b8047 !important;
  }
  .ds-btn--primary:hover, .ds-btn--conversion:hover, .ds-btn--save:hover {
    background-color: #4a9a58 !important;
    border-color: #4a9a58 !important;
  }
  .ds-btn--primary .ds-btn__label, .ds-btn--conversion .ds-btn__label,
  .ds-btn--primary .ds-btn__icon, .ds-btn--conversion .ds-btn__icon { color: #ffffff !important; }
  /* tertiary / secondary / flat / monochrome / control / round buttons
     -> dark elevated (the white "Planen"/"Drucken"/"Folgen" pills are
     .ds-btn--secondary and need the same dark fill) */
  .ds-btn--tertiary, .ds-btn--secondary, .ds-btn--flat, .ds-btn--monochrome,
  .ds-btn--control, .ds-btn--round, .ds-btn--close {
    background-color: #21262d !important;
    color: #e6edf3 !important;
    border-color: #2d333b !important;
  }
  .ds-btn--tertiary:hover, .ds-btn--secondary:hover, .ds-btn--flat:hover,
  .ds-btn--monochrome:hover, .ds-btn--control:hover, .ds-btn--round:hover { background-color: #2d333b !important; }
  .ds-btn--tertiary .ds-btn__label, .ds-btn--secondary .ds-btn__label,
  .ds-btn--flat .ds-btn__label,
  .ds-btn--monochrome .ds-btn__label { color: #e6edf3 !important; }
  .ds-btn__icon, .ds-btn--round .ds-btn__icon { fill: #c4cdd6 !important; }

  /* ====================================================================
     Filter chips / tabs / context menus / overlays (search + recipe)
     ==================================================================== */
  .ds-filter-chip, .ds-chip {
    background-color: #1c2128 !important;
    color: #c4cdd6 !important;
    border-color: #2d333b !important;
  }
  .ds-filter-chip:hover { background-color: #2d333b !important; }
  .ds-filter-chip__label { color: #c4cdd6 !important; }
  .ds-filter-chip__icon { fill: #c4cdd6 !important; }

  .ds-tab-nav, .ds-tab-nav__item { background-color: transparent !important; }
  .ds-tab-nav__link { color: #c4cdd6 !important; }
  .ds-tab-nav__link--plus { color: #d6a93b !important; } /* PLUS = gold accent */

  .ds-context-menu, .ds-context-menu__flyout, .ds-context-menu__flyout-content,
  .ds-context-menu__body, .ds-context-menu__head, .ds-context-menu__footer {
    background-color: #1c2128 !important;
    color: #e6edf3 !important;
    border-color: #2d333b !important;
  }
  .ds-context-menu__btn, .ds-context-menu__action-link { color: #e6edf3 !important; }
  .ds-context-menu__action-item:hover, .ds-context-menu__btn:hover { background-color: #2d333b !important; }
  .ds-context-menu__action-icon { fill: #c4cdd6 !important; }

  .ds-overlay, .ds-overlay__inner, .ds-overlay__body, .ds-overlay__content,
  .ds-overlay__head, .ds-overlay__footer {
    background-color: #1c2128 !important;
    color: #e6edf3 !important;
    border-color: #2d333b !important;
  }
  .ds-overlay__title { color: #e6edf3 !important; }
  .ds-snackbar-container { background-color: #21262d !important; color: #e6edf3 !important; }

  /* ====================================================================
     Login / registration page (chefkoch.de/benutzer/einloggen) — the
     "Jetzt anmelden" card ships a cream #f6f7f4 .form-container plate around
     the (already-dark) e-mail input, so it reads as a bright card on the dark
     page. Darken the card + lift its divider/copy; the brand social-login
     chips (Apple/Google/Facebook) keep their own circular styling.
     ==================================================================== */
  .form-container, .email-form-container,
  .form-container.email-form-container {
    background-color: #1c2128 !important;
    border-color: #2d333b !important;
  }
  .email-form-container__divider, .email-form-container__divider span {
    color: #9aa5af !important;
  }

  /* ====================================================================
     Forms / inputs / choices (search filters, comments)
     ==================================================================== */
  input, textarea, select, .ds-input {
    background-color: #1c2128 !important;
    color: #e6edf3 !important;
    border-color: #2d333b !important;
  }
  input::placeholder, textarea::placeholder, .ds-input::placeholder { color: #8b949e !important; }
  .ds-form-item, .ds-form-item__control { background-color: transparent !important; }
  .ds-choice__label, .ds-choices__item { color: #c4cdd6 !important; }
  .ds-choice__input { accent-color: #3b8047 !important; }

  /* ====================================================================
     Dividers / rules
     ==================================================================== */
  .ds-divider, .ds-divider--solid, .ds-divider--flat, hr {
    border-color: #2d333b !important;
    color: #2d333b !important;
    background-color: #2d333b !important;
  }

  /* ====================================================================
     Ratings — preserve the gold stars + brand badges
     The star widget uses --rating-stars-item-size and gold fills; we
     only ensure the rating value text is light and the gold survives.
     ==================================================================== */
  [class*="rating"] [class*="value"],
  [class*="rating"] [class*="count"],
  .ds-rating-avg, .ds-rating__value, .recipe-header__rating-value { color: #e6edf3 !important; }
  /* Rating stars are ck-icons GLYPHS (i.chefkoch-icons inside li.ds-rating__stars-item),
     coloured gold #ffbd1e by the site. The broad li{} + .chefkoch-icons{} greys clobber
     that gold — restore it (shape, not colour, conveys the partial fill). Never invert
     any SVG gold star fills either. */
  .ds-rating__stars-item,
  .ds-rating__stars-item .chefkoch-icons,
  .ds-rating__stars-item i { color: #ffbd1e !important; }
  .ds-rating--empty .ds-rating__stars-item,
  .ds-rating--empty .ds-rating__stars-item .chefkoch-icons { color: #565c64 !important; }
  [class*="rating"] svg [fill="#FFC107"] { /* leave gold svg fill untouched */ }

  /* PLUS badge keeps a gold pill */
  .ds-plus-badge {
    background-color: #d6a93b !important;
    color: #14181d !important;
    border-color: #d6a93b !important;
  }
  .ds-plus-badge * { color: #14181d !important; }

  /* ====================================================================
     Social icons / misc accents
     ==================================================================== */
  .ds-social-icons__item { background-color: #21262d !important; }
  .ds-social-icons__item svg { fill: #c4cdd6 !important; }
  .ds-social-icons__headline { color: #c4cdd6 !important; }
  .ds-card-badge { background-color: rgba(13,17,23,0.7) !important; color: #e6edf3 !important; }
  .ds-card-badge__icon { fill: #e6edf3 !important; }

  /* ====================================================================
     Footer  ("w-" shell)
     ==================================================================== */
  .w-footer, .w-footer.w-scope, footer {
    background-color: #0d1117 !important;
    color: #c4cdd6 !important;
    border-top: 1px solid #262c33 !important;
  }
  .w-footer a, footer a, .w-footer__menu-link { color: #c4cdd6 !important; }
  .w-footer a:hover, footer a:hover { color: #4cae5e !important; }

  /* ====================================================================
     Ad surrounds — darken the frame/slot, never the iframe content
     ==================================================================== */
  [class*="adit"], [class*="ad-slot"], [class*="advertising"],
  [id^="iqadtile"], [id*="ad_"], .ad-label, .ck-column-consent,
  spark-ad, .ad-wrapper, .ad-container, .recipe-list__dmomain_2,
  .recipe-list__dmomain_3, .recipe-list__dmomain_4 {
    background-color: #14181d !important;
  }
  spark-ad, .ad-wrapper { color: #c4cdd6 !important; }
  ins.adsbygoogle, [id^="google_ads"], [id*="div-gpt-ad"] { background-color: #14181d !important; }
  /* Taboola "Empfehlungen für dich" recommendation feed: its section header
     ("tbl-feed-header-text") ships hardcoded black and renders in the MAIN
     document (not an iframe) so it reads black-on-dark — lift to light. The
     sponsored cards keep their own imagery/labels untouched. */
  .tbl-feed-header-text, .trc_rbox_header_span, .tbl-read-more-text {
    color: #e6edf3 !important;
  }
  /* Taboola "spotlight" recipe cards ship a cream #f6f7f4 videoCube surface;
     our broad text rule already lifted the card title to light, leaving
     light-on-cream. Taboola's own cross-origin sheet re-asserts the cream with
     !important AFTER our inject, so a plain class rule loses the order-tie —
     we out-specify it via the stable #internal_trc / taboola wrapper. Darken
     the card body + kill the white bottom fade overlay so the title reads. */
  div[id^="internal_trc"] div.videoCube.trc_spotlight_item,
  div[id^="internal_trc"] div.videoCube,
  div[id*="taboola"] div.videoCube,
  .videoCube.trc_spotlight_item {
    background-color: #1c2128 !important;
  }
  .trc_exclude_overlay.trc_fade, .videoCube .trc_fade {
    background-color: transparent !important;
    background-image: none !important;
  }

  /* ====================================================================
     Magazine editorial light panels (highlight teaser, collection gallery,
     list-view recipe row) — these ship a cream/white surface (incl. a
     full-size ::before) so our light heading/body text washes out on it.
     Force the panel + its pseudo to the elevated dark surface.
     ==================================================================== */
  .ds-highlight-teaser__content, .ds-collection-gallery__body,
  .ds-list-view-item, .ds-list-view-item--recipe {
    background-color: #1c2128 !important;
    border-color: #2d333b !important;
  }
  .ds-highlight-teaser__content::before, .ds-highlight-teaser__content::after,
  .ds-collection-gallery__body::before, .ds-collection-gallery__body::after,
  .ds-list-view-item::before, .ds-list-view-item--recipe::before {
    background-color: #1c2128 !important;
    background-image: none !important;
  }
  .ds-highlight-teaser__content .ds-highlight-teaser__headline,
  .ds-collection-gallery__body .ds-collection-gallery__headline,
  .ds-list-view-item__title { color: #e6edf3 !important; }
  /* category eyebrow ("THEMENWELT", "NEUHEITEN") ships brand-dark #212018
     which now sits dark-on-dark on the elevated panel -> muted grey */
  .ds-text-category, .ds-highlight-teaser__content .ds-text-category,
  .ds-collection-gallery__body .ds-text-category { color: #9aa5af !important; }
  .ds-highlight-teaser__content p, .ds-collection-gallery__body p,
  .ds-list-view-item span, .ds-list-view-item__meta { color: #c4cdd6 !important; }

  /* pagination: the ACTIVE page number ships a dark brand-green #3b8047
     that fails contrast on the base dark page -> lift to the light accent */
  .ds-pagination__item--active, .ds-pagination__item--active a {
    color: #6fd382 !important;
  }

  /* ====================================================================
     Legacy COMMUNITY / forum frontend (chefkoch.de/forum/* — a separate
     old template not built from the ds-* design system). Its surfaces
     ship near-white (#page, the box "gradient" header strips, per-post
     author columns) with light gradient images; our light text then
     washes out. Repaint the legacy chrome to the dark palette.
     ==================================================================== */
  #page { background-color: #14181d !important; }
  .content-box, .content-wrapper, .content.no-sidebar, #content-1,
  #sidebar, #sidebar .box {
    background-color: transparent !important;
    border-color: #2d333b !important;
  }
  /* box header strips carry a light gradient IMAGE behind the (now light)
     titles -> kill the image, give an elevated dark fill */
  .content-box-gradient, .forum-group-gradient, .box-gradient {
    background-color: #1c2128 !important;
    background-image: none !important;
    border-color: #2d333b !important;
  }
  .content-box-headline, .forum-group-title, .box-headline,
  .content-box-headline a, .forum-group-title a { color: #e6edf3 !important; }
  /* per-post author column (white box on the left of each message) +
     the post date header strip + avatar frame. These also carry a LIGHT
     CDN gradient background-IMAGE painted over the bg-color (a url(), so
     the gradient-only audit misses it) — kill the image too. */
  .forum-message-author, .forum-message-author--thread-poster,
  .forum-message-header, .user-image {
    background-color: #1c2128 !important;
    background-image: none !important;
    border-color: #2d333b !important;
  }
  .forum-message-author a { color: #4cae5e !important; }
  .forum-message, .forum-message-text, .forum-message-wrapper {
    background-color: transparent !important;
    color: #c4cdd6 !important;
  }
  /* highlighted / sticky thread row (light-yellow) -> elevated dark */
  tr.thread-highlighted, tr.rowclick.thread-highlighted {
    background-color: #20222a !important;
  }
  tr.thread-highlighted td, tr.thread-highlighted a { color: #c4cdd6 !important; }
  /* thread-list ROW HOVER ships a light #efefef (hover-only, audit-blind) ->
     elevated dark so hovering a thread doesn't flash bright white */
  .search-result-table tr.rowclick:hover, tr.rowclick:hover {
    background-color: #1c2128 !important;
  }
  tr.thread-highlighted a.thread-title, tr.thread-highlighted .thread a { color: #4cae5e !important; }
  /* bootstrap-style info alerts in the reply box (light blue) */
  .alert, .alert-info {
    background-color: #1c2128 !important;
    color: #c4cdd6 !important;
    border-color: #2d333b !important;
  }
  /* forum tables / rows */
  .search-result-table, .search-result-table td, .search-result-table th,
  .forum-list, .forum-list td { background-color: transparent !important; }
  /* legacy pagination: the current-page pill ships light-grey #efefef */
  .pagination-item { color: #c4cdd6 !important; }
  .pagination-item-current {
    background-color: #2d333b !important;
    color: #e6edf3 !important;
    border-color: #2d333b !important;
  }
  /* forum-thread pagination (ck-pagination component, distinct from the
     search-list ds-pagination): the disabled "zurück" prev button ships a
     light #ddd fill, and the green "weiter" next button's white label was
     recolored green-on-green by the global a{} rule -> restore white */
  .ck-pagination__link { background-color: transparent !important; color: #4cae5e !important; }
  .ck-pagination__link--dummy,
  .ck-pagination__link-prevnext--prev.ck-pagination__link--dummy {
    background-color: #21262d !important;
    color: #8b949e !important;
    border-color: #2d333b !important;
  }
  .ck-pagination__link-prevnext--next { color: #ffffff !important; }
  .ck-pagination__link-prevnext--next .ck-icon,
  .ck-pagination__link-prevnext--next svg { fill: #ffffff !important; }
  .ck-pagination__link--active, .ck-pagination__link--current { color: #6fd382 !important; }

  /* legacy styleguide secondary ("--light") button (forum reply-box hint
     "Zur letzten Seite springen und antworten") ships a dark-green #537a29
     label that fails contrast on the dark page -> elevated chip + accent */
  a.sg-button.sg-button--light, .sg-button.sg-button--light {
    background-color: #21262d !important;
    color: #4cae5e !important;
    -webkit-text-fill-color: #4cae5e !important;
    border-color: #2d333b !important;
  }
  a.sg-button.sg-button--light:hover, .sg-button.sg-button--light:hover {
    background-color: #2d333b !important;
    color: #6fd382 !important;
    -webkit-text-fill-color: #6fd382 !important;
  }
  .sg-button.sg-button--light .sg-icon, .sg-button.sg-button--light svg { fill: #4cae5e !important; }
  /* legacy forum tab strip: the bar ships light-grey #eee and the active
     tab (.tab-nav-item.on) ships solid white with light-grey text */
  ul.tab-nav, .tab-nav {
    background-color: #1c2128 !important;
    border-color: #2d333b !important;
  }
  .tab-nav-item { background-color: transparent !important; }
  .tab-nav-item.on, li.tab-nav-item.on {
    background-color: #14181d !important;
    color: #e6edf3 !important;
  }
  .tab-nav-item a { color: #4cae5e !important; }
  .tab-nav-item.on a { color: #e6edf3 !important; }

  /* ====================================================================
     Legacy SUPPORT / 404 error template (chefkoch.de/hilfe and any dead
     URL) — a separate old layout wrapped in #page-wrapper with white/sand
     <section> bands (background--white / background--sand). Our shared h/p
     rules already lift its copy to light, so the light text just needs the
     bands darkened; the sand search band's white .search wrapper -> elevated.
     ==================================================================== */
  #page-wrapper { background-color: #14181d !important; }
  section.background--white, section.background--sand {
    background-color: #14181d !important;
  }
  section.background--sand .search, .search-bar .search {
    background-color: #1c2128 !important;
    border-color: #2d333b !important;
  }
  /* this template's header logo is a two-path SVG: the wordmark path carries
     no fill (renders black -> invisible on dark) while the hat keeps its own
     green (#618f30). Lift only the fill-less wordmark path. */
  a.header__logo svg path:not([fill]) { fill: #e6edf3 !important; }
  .header__nav a, .header a { color: #4cae5e !important; }

  /* ====================================================================
     Safety nets
     ==================================================================== */
  ::selection { background-color: #3b8047 !important; color: #ffffff !important; }
  [style*="background-color: rgb(255, 255, 255)"],
  [style*="background:#fff"], [style*="background: #fff"],
  [style*="background-color:#fff"],
  [style*="background-color: rgb(246, 247, 244)"] { background-color: #1c2128 !important; }
}
